local card={api_version=1,id="NEW1_036",name="Commanding Shout",text="Your minions can't be reduced below 1 Health this turn. Draw a card.",set="EXPERT1",type="spell",class="warrior",rarity="rare",cost=2}
function card.on_play(ctx,self)ctx:set_data(self,"active",1);ctx:draw(ctx:controller(self),1)end
card.triggers={{event="damaged",timing="before",active_zones={"graveyard"},condition=function(ctx,self,e)local t=ctx:entity(e.target);return ctx:get_data(self,"active")==1 and t.type=="minion"and t.controller==ctx:controller(self)and e.amount>=t.health end,effect=function(ctx,self,e)ctx:set_event_amount(e,math.max(0,ctx:entity(e.target).health-1))end},{event="turn_ended",timing="after",active_zones={"graveyard"},condition=function(ctx,self,e)return ctx:get_data(self,"active")==1 and e.player==ctx:controller(self)end,effect=function(ctx,self)ctx:set_data(self,"active",0)end}}
return card
